var setup = SugarCube.setup;
var lc = (setup.help_data || {}).locationCanvases || {};
var slugs = ['scene_hallway_frank_pass', 'scene_kitchen_frank_coffee_alone', 'scene_living_room_frank_radio', 'scene_porch_frank_evening_smoke', 'scene_kitchen_late_night_raid', 'scene_yard_frank_mending_fence', 'scene_living_room_frank_evening_paper', 'scene_kitchen_frank_afternoon_alone', 'scene_hallway_frank_morning_pass', 'scene_living_room_frank_dusk', 'scene_back_porch_frank_weekend_morning', 'scene_yard_frank_late_afternoon', 'scene_hallway_franks_door_evening'];
var results = [];
for (var loc in lc) {
  var arr = lc[loc] || [];
  for (var i = 0; i < arr.length; i++) {
    var c = arr[i];
    var pname = (c.passageName || '');
    for (var j = 0; j < slugs.length; j++) {
      if (pname.indexOf(slugs[j]) !== -1) {
        var conds = (c.conditions && c.conditions.items) || [];
        var flagKeys = [];
        var traitChecks = [];
        for (var k = 0; k < conds.length; k++) {
          var item = conds[k];
          if (item.type === 'flag') flagKeys.push(item.flag_key + '=' + item.operator);
          if (item.type === 'trait') traitChecks.push(item.trait_key + ' ' + item.operator + ' ' + item.value);
        }
        results.push({slug: slugs[j], maxPerDay: c.maxPerDay, chance: c.chance, flags: flagKeys, traits: traitChecks});
      }
    }
  }
}
return JSON.stringify(results, null, 2);

var setup = SugarCube.setup;
var lc = (setup.help_data || {}).locationCanvases || {};
var slugs = ['scene_hallway_frank_pass', 'scene_kitchen_frank_coffee_alone', 'scene_living_room_frank_radio', 'scene_porch_frank_evening_smoke', 'scene_kitchen_late_night_raid', 'scene_yard_frank_mending_fence', 'scene_living_room_frank_evening_paper', 'scene_kitchen_frank_afternoon_alone', 'scene_hallway_frank_morning_pass', 'scene_living_room_frank_dusk', 'scene_back_porch_frank_weekend_morning', 'scene_yard_frank_late_afternoon', 'scene_hallway_franks_door_evening'];
var results = [];
var seen = {};
for (var loc in lc) {
  var arr = lc[loc] || [];
  for (var i = 0; i < arr.length; i++) {
    var c = arr[i];
    var pname = (c.passageName || '');
    for (var j = 0; j < slugs.length; j++) {
      if (pname.indexOf(slugs[j]) !== -1 && !seen[slugs[j]]) {
        seen[slugs[j]] = true;
        var conds = (c.conditions && c.conditions.items) || [];
        var flagKeys = [];
        for (var k = 0; k < conds.length; k++) {
          if (conds[k].type === 'flag') flagKeys.push(conds[k].flag_key);
        }
        var hasMutex = flagKeys.some(function(f){ return f.indexOf('_used') !== -1 || f.indexOf('_today') !== -1; });
        results.push({slug: slugs[j], maxPerDay: c.maxPerDay !== undefined ? c.maxPerDay : null, chance: c.chance, flags: flagKeys, mutex: hasMutex});
      }
    }
  }
}
return JSON.stringify(results, null, 2);
